"""matplotlib.backends.backend_cairo — cairo backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_cairo import
FigureCanvasCairo`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasCairo = _make_canvas('FigureCanvasCairo', 'png')
FigureManagerCairo = _make_manager('FigureManagerCairo')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasCairo
FigureManager = FigureManagerCairo

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendCairo', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show


# ─── Added: missing public names (stub classes/funcs) ────────
class GraphicsContextCairo:
    """Stub: real matplotlib defines this in the cairo backend."""
    def __init__(self, *args, **kwargs): pass

class RendererCairo:
    """Stub: real matplotlib defines this in the cairo backend."""
    def __init__(self, *args, **kwargs): pass
